'use strict';(()=>{const B=RPG_BOOKS,bridge=RPG_ACCOUNT_BRIDGE,$=s=>dialog.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.ceil(n).toLocaleString('ko-KR');const dialog=document.createElement('dialog');dialog.className='books-dialog';dialog.id='books-dialog';dialog.innerHTML='<header><div><small>EXPEDITION CODEX</small><h2>전투 교본</h2></div><button data-books-close aria-label="전투 교본 닫기">×</button></header><div class="books-scroll"><p id="books-notice" role="status" aria-live="polite"></p><div id="books-body"></div></div>';document.body.append(dialog);const detail=document.createElement('dialog');detail.className='books-detail';detail.setAttribute('aria-labelledby','books-detail-title');document.body.append(detail);let payload,hero=0,filter='전체',chosen=null,message='';function refresh(){payload=bridge.books.view();}function say(s){message=s;$('#books-notice').textContent=s;}
function render(){const h=payload.heroes[hero],book=payload.books,owned=book.owned,list=book.loadouts[hero]||[],n=B.slots(h.level),rec=B.recommend(hero,h.cell,RPG_DATA),def=id=>B.defs.find(d=>d.id===id);$('#books-body').innerHTML=`<section class="books-character"><div><small>원정대 공통 해금 · 캐릭터별 장착</small><label for="books-hero">교본을 장착할 캐릭터</label><select id="books-hero">${payload.heroes.map((h,i)=>h.recruited?`<option value="${i}" ${hero===i?'selected':''}>${esc(RPG_DATA.characters[i].name)} · Lv.${h.level}</option>`:'').join('')}</select></div><strong>${fmt(h.gold)}<small> G</small></strong></section><section class="books-loadout"><div class="books-section-title"><h3>현재 장착</h3><span>${list.length} / ${n}</span></div><div class="books-slots">${[0,1,2].map(i=>`<button ${i<n?`data-slot="${i}"`: 'disabled'} class="${list[i]?'filled':''}"><small>${i<n?`SLOT 0${i+1}`:'잠김'}</small><b>${i>=n?'Lv.'+[30,45,60][i]:list[i]?esc(def(list[i]).name):'＋ 교본 선택'}</b>${list[i]?'<span>눌러서 해제</span>':''}</button>`).join('')}</div><p>${n?list.length?list.map(id=>esc(def(id).text)).join('<br>'):'아래 교본을 선택해 첫 특성을 장착하세요.':'Lv.30 / 45 / 60에 장착 칸이 열려요.'}</p></section><div class="books-meta"><span>보유 교본 <b>${owned.length} / ${B.defs.length}</b></span><span>실패 없음 · 교체 무료</span></div><nav class="books-filters" aria-label="교본 분류">${['전체','사냥','보스','생존·지원','소환'].map(x=>`<button data-filter="${x}" aria-pressed="${x===filter}">${x}</button>`).join('')}</nav><div class="books-grid">${B.defs.filter(d=>filter==='전체'||d.group===filter).sort((a,b)=>Number(rec.includes(b.id))-Number(rec.includes(a.id))).map(d=>{const have=owned.includes(d.id),eq=list.includes(d.id),ok=B.compatible(d.id,hero,h.cell,RPG_DATA);return `<button class="book-card ${eq?'equipped':''}" data-book="${d.id}"><span class="book-symbol" aria-hidden="true">${{사냥:'✦',보스:'♜',소환:'◇','생존·지원':'✚',기본:'▤'}[d.group]}</span><span class="book-copy"><small>${d.group}${rec.includes(d.id)&&ok?' · 추천':''}</small><strong>${d.name}</strong><span>${d.text}</span></span><span class="book-card-state ${eq?'on':''}">${eq?'장착 중':have?'보유':d.cost?fmt(d.cost)+' G':'Lv.30 무료'}<small>${!ok?'현재 직업에 효과 없음':have?'상세 보기':'원정대 공통 해금'}</small></span></button>`;}).join('')}</div><p class="books-footnote">현재 사냥에 적용됩니다. 조건부 효과는 기본 전투력 숫자에 합산하지 않아요.<br>구매 골드는 선택한 캐릭터에게서 차감됩니다.</p>`;$('#books-hero').onchange=e=>{hero=Number(e.target.value);render();};say(message);}
function show(id){chosen=id;const d=B.defs.find(x=>x.id===id),h=payload.heroes[hero],have=payload.books.owned.includes(id),eq=payload.books.loadouts[hero]?.includes(id),ok=B.compatible(id,hero,h.cell,RPG_DATA),n=B.slots(h.level);detail.innerHTML=`<button class="books-detail-close" data-detail-close aria-label="교본 상세 닫기">×</button><small>${d.group} · ${have?'보유 교본':'영구 해금'}</small><h2 id="books-detail-title">${d.name}</h2><p>${d.text}</p><div class="books-detail-info">${ok?'이 캐릭터에게 적용할 수 있어요.':'현재 직업에는 효과가 없어 장착할 수 없어요.'}<br>원정대 공통 해금 · 실패 없음 · 장착 교체 무료</div>${!have?`<dl><div><dt>결제 캐릭터</dt><dd>${esc(RPG_DATA.characters[hero].name)}</dd></div><div><dt>보유 골드</dt><dd>${fmt(h.gold)} G</dd></div><div><dt>구매 후</dt><dd>${fmt(Math.max(0,h.gold-d.cost))} G</dd></div></dl><button class="books-primary" data-buy="${id}" ${h.level<30||h.gold<d.cost||!d.cost?'disabled':''}>${h.level<30?'Lv.30부터 해금 가능':!d.cost?'Lv.30에 무료 지급':h.gold<d.cost?'골드가 부족해요':fmt(d.cost)+' G로 해금'}</button>`:`<button class="books-primary" data-equip="${id}" ${!ok||!n?'disabled':''}>${!n?'Lv.30에 장착 가능':eq?'장착 해제':'장착하기'}</button><div id="books-replace"></div>`}<p class="books-detail-status" role="status" aria-live="polite"></p>`;if(!detail.open)detail.showModal();}
function change(action,id,replace){try{const result=bridge.books.change(action,id,hero,replace);if(!result)throw Error('조건을 다시 확인해 주세요.');refresh();message=action==='buy'?'교본 해금 완료 · 장착하기를 눌러 적용하세요.':'장착 구성을 저장했어요.';render();if(action==='buy'){show(id);detail.querySelector('.books-detail-status').textContent='해금 완료 · 다른 캐릭터도 사용할 수 있어요.';}else detail.close();}catch(e){if(detail.open)detail.querySelector('.books-detail-status').textContent=e.message;else say(e.message);}}
function close(){detail.close();dialog.close();bridge.books.edit(false);bridge.pause(false);document.dispatchEvent(new Event('rpg:hub-open'));}document.addEventListener('rpg:books-open',e=>{try{bridge.books.edit(true);refresh();hero=Number.isInteger(e.detail?.hero)&&payload.heroes[e.detail.hero]?.recruited?e.detail.hero:Number.isInteger(payload.active)&&payload.heroes[payload.active]?.recruited?payload.active:payload.heroes.findIndex(h=>h.recruited);if(hero<0)throw Error('먼저 캐릭터를 원정대에 추가해 주세요.');message='Lv.30부터 전투 숙련 교본이 무료로 지급됩니다.';filter='전체';render();bridge.pause(true);dialog.showModal();}catch(e){bridge.books.edit(false);$('#books-body').innerHTML='<p class="books-footnote">캐릭터를 원정대에 추가하면 교본을 확인할 수 있어요.</p>';say(e.message);bridge.pause(true);if(!dialog.open)dialog.showModal();}});dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-books-close'))return close();if(b.dataset.filter){filter=b.dataset.filter;render();}if(b.dataset.book)show(b.dataset.book);if(b.dataset.slot!==undefined){const id=payload.books.loadouts[hero]?.[Number(b.dataset.slot)];if(id)change('equip',id);else{filter='전체';render();$('#books-notice').textContent='목록에서 교본을 선택해 장착하세요.';}}});detail.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-detail-close'))return detail.close();if(b.dataset.buy)return change('buy',b.dataset.buy);if(b.dataset.replace)return change('equip',chosen,b.dataset.replace);if(b.dataset.equip){const list=payload.books.loadouts[hero]||[];if(!list.includes(chosen)&&list.length>=B.slots(payload.heroes[hero].level))detail.querySelector('#books-replace').innerHTML='<p>교체할 교본을 선택하세요.</p>'+list.map(id=>`<button data-replace="${id}">${B.defs.find(d=>d.id===id).name} 교체</button>`).join('');else change('equip',chosen);}});document.addEventListener('rpg:progress-applied',()=>{if(dialog.open){detail.close();dialog.close();bridge.books.edit(false);bridge.pause(false);}});document.addEventListener('rpg:session-state',e=>{if(e.detail.blocked&&dialog.open){detail.close();dialog.close();bridge.books.edit(false);bridge.pause(false);}});})();
